         // Deletion fails.
         (s, DeleteResponse{res: Err(delete_request_admission_check(req, s)->0)})
     } else {
         // Deletion succeeds.
         let obj = s.resources[req.key];
         if obj.metadata.finalizers is Some && obj.metadata.finalizers->0.len() > 0 {
